import {
  AngleSliderRoot,
  AngleSliderTrack,
  AngleSliderThumb,
  AngleSliderValueText,
  AngleSliderHiddenInput,
} from '@uifn/components-solid/angle-slider'
import '@uifn/components/styles.css'

export function Example() {
  return (
    <AngleSliderRoot defaultValue={225} min={0} max={360} step={1} name="rotation">
      <AngleSliderTrack />
      <AngleSliderThumb />
      <AngleSliderValueText>225°</AngleSliderValueText>
      <AngleSliderHiddenInput />
    </AngleSliderRoot>
  )
}

import {
  CheckboxRoot,
  CheckboxControl,
  CheckboxIndicator,
  CheckboxLabel,
  CheckboxHiddenInput,
} from '@uifn/components-solid/checkbox'
import '@uifn/components/styles.css'

export function Example() {
  return (
    <CheckboxRoot defaultChecked name="notifications">
      <CheckboxControl type="button">
        <CheckboxIndicator>✓</CheckboxIndicator>
      </CheckboxControl>
      <CheckboxLabel>Email notifications</CheckboxLabel>
      <CheckboxHiddenInput />
    </CheckboxRoot>
  )
}

import {
  TimerRoot,
  TimerValue,
  TimerStart,
  TimerPause,
  TimerReset,
  TimerStatus,
} from '@uifn/components-solid/timer'
import '@uifn/components/styles.css'

export function Example() {
  return (
    <TimerRoot duration={60000} defaultRemaining={42000} aria-label="Timer example">
      <TimerValue>05:00</TimerValue>
      <TimerStart type="button">Start</TimerStart>
      <TimerPause type="button">Pause</TimerPause>
      <TimerReset type="button">Reset</TimerReset>
      <TimerStatus>Ready</TimerStatus>
    </TimerRoot>
  )
}

